package com.aditya.fefo.service; import com.aditya.fefo.dto.AuditDtos.AuditResponse; import com.aditya.fefo.repository.AuditLogRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class AuditService {private final AuditLogRepository r;public AuditService(AuditLogRepository r){this.r=r;}public List<AuditResponse> list(){return r.findTop200ByOrderByCreatedAtDesc().stream().map(a->new AuditResponse(a.getId(),a.getActorId(),a.getAction(),a.getEntityType(),a.getEntityId(),a.getQuantity(),a.getProductId(),a.getBatchId(),a.getReservationId(),a.getReason(),a.getCreatedAt())).toList();}}
